      case 'n':
        cp = '\n';
        break;
      case 'r':
        cp = '\r';
        break;
      case 't':
        cp = '\t';
        break;
      case 'f':
        cp = '\f';
        break;
      case 'v':
        cp = '\v';
        break;
      case 'b':
        if (!in_class)
          Invalid("word-boundary regex assertions are unsupported");
        cp = '\b';
        break;
      case '0':
        if (Peek() >= '0' && Peek() <= '9')
          Invalid("legacy octal regex escapes are unsupported");
        cp = 0;
        break;
      case 'c':
